{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "2ykwang-agent-skills",
  "description": "Skills for AI coding agents",
  "owner": {
    "name": "2ykwang",
    "url": "https://github.com/2ykwang"
  },
  "plugins": [
    {
      "name": "code-history",
      "source": "./plugins/code-history",
      "description": "Trace git history of specific code \u2014 find when functions, patterns, or files were added, modified, or removed, and explain the intent behind each change.",
      "version": "0.0.1",
      "category": "development"
    },
    {
      "name": "django-ticket-triage",
      "source": "./plugins/django-ticket-triage",
      "description": "Analyze a Django Trac ticket and produce a triage recommendation report.",
      "version": "0.1.1",
      "category": "integrations"
    },
    {
      "name": "docs",
      "source": "./plugins/docs",
      "description": "Code documentation agent \u2014 write/update docs with /docs write, check status with /docs check. Minimal code blocks, reference pointer based.",
      "version": "0.0.2",
      "category": "productivity"
    },
    {
      "name": "html-visual",
      "source": "./plugins/html-visual",
      "description": "Generate an interactive single-file HTML visualization (mockup, wireframe, ERD, flowchart, chart, slides, architecture diagram, dashboard, timeline, mindmap, kanban, table).",
      "version": "0.0.1",
      "category": "design-frontend"
    },
    {
      "name": "ralph-loop-template",
      "source": "./plugins/ralph-loop-template",
      "description": "Generates iterable checklist PROMPT files for Ralph Loop from plan files or current context, and provides the /ralph-loop execution command.",
      "version": "0.0.2",
      "category": "development"
    },
    {
      "name": "write-pr",
      "source": "./plugins/write-pr",
      "description": "Analyzes git diff and commit history to write PR title and description based on the project's PR template.",
      "version": "0.0.3",
      "category": "productivity"
    }
  ]
}
